WITH enriched AS (SELECT *, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region, city), 4) AS sqft_share, LAG(sqft, 2) OVER (ORDER BY sqft ASC, id ASC) AS prev_sqft, ROW_NUMBER() OVER w_hist AS row_seq, SUM(sqft) OVER (PARTITION BY city ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft FROM stores WINDOW w_hist AS (PARTITION BY city ORDER BY opened_date ASC, id ASC)) SELECT id, store_name, city, region, opened_date, sqft, sqft_share, prev_sqft FROM enriched
